def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # The distinctive marker is an L made of a long horizontal and vertical arm.
    marker = None
    for comp in comps:
        color, cells = comp
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        hh, ww = max(rs) - min(rs) + 1, max(cs) - min(cs) + 1
        if hh >= 3 and ww >= 3:
            rows = Counter(r for r, c in cells)
            cols = Counter(c for r, c in cells)
            if max(rows.values()) >= 3 and max(cols.values()) >= 3:
                marker = comp
                break

    if marker is None:
        return out

    mark_color, mark_cells = marker

    # Recolor the closest separate object to the marker.
    best, target = None, None
    for color, cells in comps:
        if cells == mark_cells:
            continue
        dist = min(abs(r-y) + abs(c-x) for r, c in mark_cells for y, x in cells)
        if best is None or dist < best:
            best, target = dist, cells

    if target:
        for r, c in target:
            out[r][c] = mark_color
    return out
