def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The large L-shaped 3 is the color key. Apply its color to the
    # matching 6 object at the opposite end of the grid.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 6 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)

    if len(objects) >= 2:
        # Color the 6 component farthest from the 3 marker.
        marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
        target = max(objects, key=lambda obj: min(
            abs(r-y) + abs(c-x) for r, c in obj for y, x in marker
        ))
        for r, c in target:
            out[r][c] = 3
    return out
